import{Q as e,X as t,ft as n,n as r}from"./chunks/framework.DE1SKwK9.js";var i=JSON.parse(`{"title":"Recon Owns Its macOS Privacy Identity","description":"","frontmatter":{"id":"decision.0001","title":"Recon Owns Its macOS Privacy Identity","status":"superseded","established-by":"proposal.0002","supersedes":[]},"headers":[],"relativePath":"decisions/0001-macos-privacy-identity.md","filePath":"decisions/0001-macos-privacy-identity.md"}`),a={name:`decisions/0001-macos-privacy-identity.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="recon-owns-its-macos-privacy-identity" tabindex="-1">Recon Owns Its macOS Privacy Identity <a class="header-anchor" href="#recon-owns-its-macos-privacy-identity" aria-label="Permalink to “Recon Owns Its macOS Privacy Identity”">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>macOS privacy grants belong to the <code>recon</code> executable itself, identified as <code>me.malstrom.recon</code>. Recon embeds that identity, re-executes itself as its own responsible process before any permission-gated work, and is signed locally with a Developer ID identity so grants survive rebuilds.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>Screen Recording and Accessibility are privacy permissions that macOS (TCC) attributes to a <em>responsible process</em>. For a command-line tool, that is the terminal, editor, or agent harness that launched it. Recon is run by many launchers. If it inherited their permissions, the same command would work under one harness and fail under another, and its evidence would not be reproducible.</p><p>macOS records a grant for a bare executable against its path and its code-signing designated requirement. The Rust toolchain ad-hoc signs builds, and an ad-hoc designated requirement is the code hash, so macOS forgets the grant on every rebuild. A Developer ID signature&#39;s requirement names the signing identifier and the team instead.</p><p>Proposal 0002 grounded these facts on macOS 27.0.1 with SIP enabled. Re-executing with the private <code>responsibility_spawnattrs_setdisclaim</code> spawn attribute made a test program responsible for itself. A bare executable with an embedded Info.plist appeared in System Settings under its bundle name. Its grant survived a rebuild signed with the same identity and installed at the same path, but a copy at another path had no grant. Wrapping the same program in an app bundle produced no permission prompt.</p><p>Every later feature that reads or drives another application&#39;s UI needs the same permissions, starting with UI interaction (#24). Changing the identifier later would invalidate every user&#39;s grants, which is why it is recorded here rather than left in one proposal.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ul><li>Recon&#39;s privacy identifier is <code>me.malstrom.recon</code>, under Mark&#39;s <code>me.malstrom.*</code> namespace for <code>malstrom.me</code>. The <code>recon</code> executable embeds an Info.plist in its <code>__TEXT,__info_plist</code> section with that <code>CFBundleIdentifier</code> and the <code>CFBundleName</code> <code>recon</code>, and its code-signing identifier is the same string.</li><li>Before doing anything that needs a privacy permission, a command makes <code>recon</code> responsible for itself. If macOS reports another process as responsible, <code>recon</code> re-executes itself once with the disclaim spawn attribute and passes on its arguments, environment, standard streams, termination signals, and exit status. If that is impossible, the command fails rather than running under the launcher&#39;s permissions. Commands that need no permission do not re-execute.</li><li>Recon checks a permission without prompting, asks macOS to request it when it is missing, and then fails with an error. The error names the permission, the executable&#39;s path, and the System Settings pane. Recon never writes to the TCC database or works around a missing grant.</li><li><code>recon</code> ships as a bare executable, not an application bundle. Users sign it locally with a Developer ID Application identity and the identifier <code>me.malstrom.recon</code> (<code>codesign --force --sign &quot;&lt;identity&gt;&quot; --identifier me.malstrom.recon &lt;path&gt;</code>). Contributors use <code>RECON_SIGNING_IDENTITY=… vp run recon:sign</code>. CI builds stay ad-hoc signed until Recon has a distribution channel, such as a Homebrew formula, that brings signing into CI. That change revises this decision.</li></ul><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to “Rationale”">​</a></h2><p>Owning the identity is the only arrangement under which a grant means the same thing in every terminal and agent harness. Recon&#39;s evidence depends on observations that can be repeated, so a grant that varies with the launcher would undermine every result built on it.</p><p>An embedded Info.plist gives the bare executable a recognizable name in System Settings without the packaging and launch semantics of an app bundle. The bare form is also the one verified to prompt and keep its grant. A Developer ID signature is the cheapest signature whose designated requirement survives a rebuild. Local signing keeps a certificate out of CI until a distribution channel needs one.</p><p>The identifier follows the owner&#39;s existing reverse-DNS convention, because any later change costs every user a fresh grant.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><ul><li><strong>Use the launcher&#39;s permissions.</strong> This needs no private interface, but grants differ between terminals and harnesses, and it would grant Recon whatever the launcher happens to hold.</li><li><strong>Wrap <code>recon</code> in an app bundle.</strong> This could make grants independent of the install path, but the one attempt produced no permission prompt. It remains a possible revision alongside notarized distribution.</li><li><strong>Ship ad-hoc signed builds only.</strong> This needs no certificate, but macOS forgets the grant on every rebuild or upgrade.</li><li><strong>Sign pull-request and release builds in CI now.</strong> This produces ready-to-grant downloads, but places a signing certificate in CI before there is a distribution channel. It was deferred until a Homebrew formula exists.</li><li><strong>Use <code>com.markmals.recon</code>.</strong> It was rejected in favor of the owner&#39;s established <code>me.malstrom.*</code> namespace.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="good" tabindex="-1">Good <a class="header-anchor" href="#good" aria-label="Permalink to “Good”">​</a></h3><ul><li>A permission grant behaves the same whichever program launches <code>recon</code>, including cron jobs and agent harnesses.</li><li>One grant per installed executable survives in-place upgrades signed with the same identifier and team.</li><li>Interaction (#24) and later UI features inherit the identity, re-execution, and permission errors instead of solving them again.</li><li>A missing permission is reported with an actionable path and pane, never hidden behind empty or partial results.</li></ul><h3 id="bad" tabindex="-1">Bad <a class="header-anchor" href="#bad" aria-label="Permalink to “Bad”">​</a></h3><ul><li>Recon depends on the private <code>responsibility_get_pid_responsible_for_pid</code> and <code>responsibility_spawnattrs_setdisclaim</code> interfaces. A macOS update can remove them, and Recon then reports the capability as unavailable.</li><li>Grants are tied to a path. Moving the executable, or running a second copy elsewhere, needs a new grant.</li><li>Keeping grants across rebuilds requires a Developer ID certificate. Without one, a user must grant again after every build.</li><li>CI downloads must be re-signed before use until CI signing exists.</li><li>The identifier must never change casually. Superseding it invalidates every existing grant.</li><li>Since macOS 15, macOS periodically asks users to reconfirm screen-recording permission, which can interrupt unattended use.</li></ul><h2 id="revision-history" tabindex="-1">Revision history <a class="header-anchor" href="#revision-history" aria-label="Permalink to “Revision history”">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Change</th><th>Proposal</th></tr></thead><tbody><tr><td>2026-10-15</td><td>Accepted this decision.</td><td>proposal.0002</td></tr><tr><td>2026-10-26</td><td>Superseded by decision.0002; original decision text preserved.</td><td>proposal.0003</td></tr></tbody></table>`,23)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};